// loaders.cjs builds exports dynamically:
//   for (const n of names) module.exports[n] = makeLoader(n);

// app.mjs (native ESM, "type": "module")
import { jsonLoader } from './loaders.cjs'; // ❌ undefined — lexer never saw it

export function configPath() {
  return jsonLoader(__dirname + '/config.json'); // ❌ __dirname is not defined in ESM
}

model.en:
Default-import the CJS dep then destructure, and rebuild __dirname from import.meta.url:

import { fileURLToPath } from 'node:url';
import { dirname } from 'node:path';
import loaders from './loaders.cjs';      // default import = module.exports itself
const { jsonLoader } = loaders;            // dynamic export is present on the real object

const __dirname = dirname(fileURLToPath(import.meta.url));

export function configPath() {
  return jsonLoader(__dirname + '/config.json');
}

Why it's right: the default import is module.exports as it exists at runtime, so jsonLoader — added via a computed key — is actually there; destructuring off it bypasses cjs-module-lexer's static guess entirely (the named import { jsonLoader } failed precisely because the lexer could not see a dynamically-assigned name). For __dirname, ESM has no module-wrapper locals, so reconstruct it from import.meta.url via fileURLToPath + dirname.

model.ru:
Default-импортируй CJS-зависимость, затем деструктурируй, и пересобери __dirname из import.meta.url:

import { fileURLToPath } from 'node:url';
import { dirname } from 'node:path';
import loaders from './loaders.cjs';      // default-импорт = сам module.exports
const { jsonLoader } = loaders;            // динамический экспорт есть на реальном объекте

const __dirname = dirname(fileURLToPath(import.meta.url));

export function configPath() {
  return jsonLoader(__dirname + '/config.json');
}

Почему верно: default-импорт — это module.exports такой, как он существует в рантайме, так что jsonLoader — добавленный вычисляемым ключом — действительно там; деструктуризация из него полностью обходит статическую догадку cjs-module-lexer (именованный импорт { jsonLoader } упал именно потому, что лексер не смог увидеть динамически присвоенное имя). Для __dirname в ESM нет локалей обёртки модуля, так что воссоздай его из import.meta.url через fileURLToPath + dirname.
